from Crypto.Util.number import *

bits = 30
p = getPrime(512)
q = getPrime(512)
n = p*q
gift = p ^ (q >> bits)
flag = b"flag{c67b2ed8-8a92-418e-abed-80acb2350992}"
e = 0x10001
d = pow(e, -1, (p-1)*(q-1))
c = pow(bytes_to_long(flag), e, n)

print(f"n = {n}")
print(f"c = {c}")
print(f"gift = {gift}")

